-- Source: FED_OSHA_ITA_300A_SUMMARY_2025 (383283 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: TOTAL_DEATHS was a bare try_to_number() (silently rounds
-- decimals) and CREATED_TIMESTAMP a bare try_to_timestamp() (pure-digit values
-- misread as epoch seconds). Live-checked: 3 of 383,283 rows are the
-- known column-shifted corruption documented in
-- models/staging/fed_osha_ita_300a_summary_2025 (e.g. a weekday-name string
-- like 'Wednesday, January 2, 3439' landed in CREATED_TIMESTAMP) -- both the
-- bare cast and the guarded one already return NULL for those 3 rows, so no
-- behavior change there, just a guard against the epoch-seconds failure mode
-- on the other 383,280. TOTAL_DEATHS is 100% whole otherwise. That staging
-- model applies NO casts at all (hand-edited passthrough, "kept as landed"),
-- so swapping to ref() would have stripped the mart's existing casts instead
-- of guarding them -- wrapped the two bare casts in place.

with source as (
    select * from {{ source('ripple_raw', 'FED_OSHA_ITA_300A_SUMMARY_2025') }}
)

select
    ID as id,
    ESTABLISHMENT_NAME as establishment_name,
    ESTABLISHMENT_ID as establishment_id,
    EIN as ein,
    COMPANY_NAME as company_name,
    STREET_ADDRESS as street_address,
    CITY as city,
    STATE as state,
    ZIP_CODE as zip_code,
    NAICS_CODE as naics_code,
    {{ ripple_num('NAICS_YEAR') }} as naics_year,
    INDUSTRY_DESCRIPTION as industry_description,
